{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Omadacycline, a complex polycyclic antibiotic with many H-bond donors/acceptors, had absolute oral bioavailability of only 0.6% in healthy adults after a high-fat meal, directly supporting low F for the similarly polar, rigid query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "In healthy volunteers, one mefloquine enantiomer showed much lower peak exposure than the other after oral dosing, suggesting stereoselective poor absorption; this indirect evidence weakly supports low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "5-Hydroxyrofecoxib, a lactone-containing drug, had oral bioavailability of 14.9% in healthy subjects, below the 20% threshold, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A subject receiving a complex macrolide-like compound showed potentially low absolute bioavailability with high oral clearance, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Epicillin had oral bioavailability of 3.9% in cystic fibrosis patients, a direct low-F measurement for a polar, ring-rich drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Galocitabine showed extremely low oral bioavailability in humans, with about half the dose excreted unchanged in urine, consistent with poor absorption of a highly polar nucleoside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "9-Nitrocamptothecin, a polycyclic lactone with a hydroxyl, has very low absolute oral bioavailability, supporting low F for the query's rigid lactone scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Tigecycline has low oral bioavailability and is administered IV only, supporting low F for a polycyclic molecule with many H-bond groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "EM574, a macrolide-like compound, had an estimated oral bioavailability of about 2% in humans, directly supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Etoposide showed high oral bioavailability (85%) in patients, which is contradictory to a low-F prediction; however, this evidence has much lower transferability (0.519) and the query lacks etoposide's glycosidic and phenolic features, so it is outweighed.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, rigid polycyclic lactone with very low predicted permeability. Multiple high-transfer experimental analogues (omadacycline, 5-hydroxyrofecoxib, epicillin, galocitabine, 9-nitrocamptothecin, tigecycline, EM574) show absolute oral bioavailability well below 20%, strongly supporting a low F prediction. The only high-F evidence (etoposide) has much lower transferability and is outweighed.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "No permeability or transporter data for the query.",
    "Etoposide high-F evidence is from a structurally distinct glycoside with lower transfer score; its applicability to the query is uncertain.",
    "Mefloquine and subject-level records provide only indirect or weak bioavailability estimates."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

